const{validateDictionaries,translator}=window.PolyglowI18n;
const{loadState,saveState,updateSettings,clearState}=window.PolyglowStorage;
const{availableCountryCodes,getLanguages,getCatalogLanguage,getLanguageDisplay,getLanguageCountryCodes,createLanguageFlags,languageFlagsHTML}=window.PolyglowLanguages;
const getLanguageFlags=()=>"";
const{demoData}=window.PolyglowDemo;
const{activityCatalog}=window.PolyglowActivities;
const{dateKey,dailyTotals,streaks,isFullMonth,goalProgress,starDays,filterSessions,activityBreakdown,subcategoryBreakdown,analyticsSummary}=window.PolyglowStats;
const motivation=window.PolyglowMotivation;

validateDictionaries();
let state=loadState();
let showFirstHero=!state.profile.hasVisited;
let t=translator(state.settings.uiLanguage);
let pendingConfirm=null;
let focusPresetMinutes=25;
let focusTicker=null;
let calendarCursor=new Date(new Date().getFullYear(),new Date().getMonth(),1,12);
let calendarSelectedDate=dateKey(new Date());
let goalFilter="active";
let insightFilters={period:"month",languageId:"",source:"",from:"",to:""};
let insightCategory=null;
let onboardingLanguageCodes=[];
