let aiBusy=false;
let aiDirty=false;
let aiTrigger=null;
const $=selector=>document.querySelector(selector);
const $$=selector=>[...document.querySelectorAll(selector)];
const todayKey=()=>{const date=new Date();return`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;};
const newId=prefix=>`${prefix}-${globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2)}`;

function applyTranslations(){
  const sessionDraft=$("#session-dialog")?.open?collectActivities():null;
  t=translator(state.settings.uiLanguage);
  refreshCustomCountryPicker();
  document.documentElement.lang=state.settings.uiLanguage;
  $$('[data-i18n]').forEach(element=>element.textContent=t(element.dataset.i18n));
  $$('[data-i18n-placeholder]').forEach(element=>element.placeholder=t(element.dataset.i18nPlaceholder));
  $$('[data-i18n-aria]').forEach(element=>element.setAttribute("aria-label",t(element.dataset.i18nAria)));
  document.title=`Polyglow — ${t("brand.subtitle")}`;
  renderDate();renderHero();renderOnboardingLanguages();renderCatalog();renderSelectedLanguages();renderMoods();renderJournal();renderFocusControls();renderCalendar();renderGoals();renderAnalytics();syncControls();renderAIJournal();if(sessionDraft){$("#activity-editor").replaceChildren(...sessionDraft.map(renderActivityRow));updateSessionTotals();}
}

function syncControls(){
  ["#language-top","#language-settings","#onboarding-ui-language"].forEach(id=>{const element=$(id);if(element)element.value=state.settings.uiLanguage;});
  $("#theme-settings").value=state.settings.theme;
  $("#music-volume").value=state.settings.volume;
  $("#background-audio").volume=state.settings.volume;
  $("#profile-name").value=state.profile.name;
  $("#profile-motivation").value=state.profile.motivation;
  const themeButton=$("#theme-toggle");
  themeButton.dataset.i18nAria=state.settings.theme==="dark"?"theme.lightLabel":"theme.darkLabel";
  themeButton.setAttribute("aria-label",t(themeButton.dataset.i18nAria));
  syncMusicControls(!$("#background-audio").paused);
}

function setLanguage(language){state=updateSettings(state,{uiLanguage:language});applyTranslations();}
function setTheme(theme){state=updateSettings(state,{theme});document.documentElement.dataset.theme=theme;syncControls();}
function renderDate(){const locale=state.settings.uiLanguage==="ru"?"ru-RU":"en-US";$("#today-date").textContent=new Intl.DateTimeFormat(locale,{weekday:"long",day:"numeric",month:"long"}).format(new Date());}

function renderHero(firstVisit=showFirstHero){const name=state.profile.name.trim();if(firstVisit){$("#hero-title").textContent=t("hero.first.title");$("#hero-subtitle").textContent=t("hero.first.subtitle");$("#hero-button-text").textContent=t("hero.first.button");return;}$("#hero-title").textContent=name?t("hero.return.title").replace("{name}",name):t("hero.return.titleNoName");$("#hero-subtitle").textContent=t("hero.return.subtitle");$("#hero-button-text").textContent=t("hero.return.button");}

function renderOnboardingLanguages(){const query=$("#onboarding-language-search")?.value||"";const items=getLanguages(query,state.settings.uiLanguage).filter(item=>item.code!=="custom");$("#onboarding-language-list").replaceChildren(...items.map(item=>{const selected=onboardingLanguageCodes.includes(item.code),button=document.createElement("button");button.type="button";button.className=selected?"selected":"";button.dataset.onboardingCode=item.code;button.setAttribute("aria-pressed",String(selected));button.innerHTML=`${languageFlagsHTML({catalogCode:item.code})}<span>${item[state.settings.uiLanguage]}</span><i aria-hidden="true">${selected?"✓":""}</i>`;return button;}));$("#onboarding-language-chips").replaceChildren(...onboardingLanguageCodes.map(code=>{const item=getCatalogLanguage(code),chip=document.createElement("span");chip.className="language-chip";chip.innerHTML=`${languageFlagsHTML({catalogCode:code})}<span>${item?.[state.settings.uiLanguage]||code}</span><button type="button" data-remove-onboarding-code="${code}" aria-label="${t("onboarding.removeLanguage")}">×</button>`;return chip;}));const field=$("#onboarding-default-field");field.hidden=onboardingLanguageCodes.length===0;const select=$("#onboarding-default-language"),current=select.value;select.replaceChildren(...onboardingLanguageCodes.map(code=>{const item=getCatalogLanguage(code);return new Option(item?.[state.settings.uiLanguage]||code,code);}));select.value=onboardingLanguageCodes.includes(current)?current:(onboardingLanguageCodes[0]||"");}

function renderCatalog(){
  const list=$("#language-list");
  const items=getLanguages($("#language-search").value,state.settings.uiLanguage);
  const activeCodes=new Set(state.languages.filter(item=>!item.archived&&item.catalogCode!=="custom").map(item=>item.catalogCode));
  list.replaceChildren(...items.map(item=>{const button=document.createElement("button");button.type="button";button.className="catalog-language";button.dataset.code=item.code;button.disabled=item.code!=="custom"&&activeCodes.has(item.code);button.innerHTML=`${languageFlagsHTML({catalogCode:item.code})}<span>${item[state.settings.uiLanguage]}</span>`;return button;}));
  $("#language-empty").hidden=items.length>0;
}

function renderSelectedLanguages(){
  const container=$("#selected-languages");
  const activeLanguages=state.languages.filter(item=>!item.archived);container.replaceChildren(...state.languages.map(item=>{const card=document.createElement("div");card.className=`selected-language${item.archived?" archived":""}`;const active=item.id===state.profile.defaultLanguageId;card.innerHTML=`${languageFlagsHTML(item)}<span><strong>${escapeHtml(getLanguageDisplay(item,state.settings.uiLanguage))}</strong>${active?`<span class="active-chip">${t("languages.defaultBadge")}</span>`:item.archived?`<span class="archived-chip">${t("languages.archivedBadge")}</span>`:""}</span><span class="language-actions">${item.archived?`<button class="text-button" type="button" data-restore-language="${item.id}">${t("languages.restore")}</button>`:`${active?"":`<button class="text-button" type="button" data-active-id="${item.id}">${t("languages.setDefault")}</button>`}<button class="text-button archive" type="button" data-archive-id="${item.id}">${t("languages.archive")}</button>`}</span>`;return card;}));
  $("#selected-languages-empty").hidden=activeLanguages.length>0;
  const top=$("#active-language-top");
  top.replaceChildren(...(activeLanguages.length?activeLanguages.map(item=>new Option(getLanguageDisplay(item,state.settings.uiLanguage),item.id)):[new Option(t("languages.choose"),"")]));
  top.disabled=activeLanguages.length===0;
  if(state.profile.defaultLanguageId)top.value=state.profile.defaultLanguageId;
  renderSelectFlag(top);
  $("#today-language-count").textContent=String(activeLanguages.length);
  $("#today-language-flags").replaceChildren(...activeLanguages.map(item=>{const flag=document.createElement("span");flag.className="today-language-flag";flag.append(createLanguageFlags(getLanguageCountryCodes(item)));const name=getLanguageDisplay(item,state.settings.uiLanguage);flag.title=name;flag.setAttribute("aria-label",name);return flag;}));
}

function renderMoods(){
  const moods=["happy","calm","curious","energized","tired","proud"];
  const selected=state.dailyMoods[todayKey()]||"";
  $("#mood-options").replaceChildren(...moods.map(mood=>{const label=document.createElement("label");label.className="mood-option";label.innerHTML=`<input type="radio" name="mood" value="${mood}" ${mood===selected?"checked":""}><span>${t(`mood.${mood}`)}</span>`;return label;}));
}

function addCatalogLanguage(code,customName="",countryCode=""){
  if(code!=="custom"&&state.languages.some(item=>item.catalogCode===code&&!item.archived)){toast(t("languages.exists"));return false;}
  const archived=state.languages.find(item=>item.catalogCode===code&&item.archived&&code!=="custom");
  if(archived){archived.archived=false;if(!state.profile.defaultLanguageId)state.profile.defaultLanguageId=archived.id;}else{const item={id:newId("language"),catalogCode:code,customName:code==="custom"?customName.trim():"",countryCode:code==="custom"?countryCode:"",archived:false,createdAt:new Date().toISOString()};state.languages.push(item);if(!state.profile.defaultLanguageId)state.profile.defaultLanguageId=item.id;}
  state=saveState(state);renderSelectedLanguages();renderCatalog();toast(t("languages.added"));return true;
}

function setActiveLanguage(id){state.profile.defaultLanguageId=id;state.profile.activeLanguageId=id;state=saveState(state);renderSelectedLanguages();}
function archiveLanguage(id){const item=state.languages.find(language=>language.id===id);if(!item)return;const hasHistory=state.sessions.some(session=>session.languageId===id);openConfirm(t("languages.archiveTitle"),t(hasHistory?"languages.archiveHistoryText":"languages.archiveText"),t("languages.archive"),()=>{item.archived=true;if(state.profile.defaultLanguageId===id)state.profile.defaultLanguageId=state.languages.find(language=>!language.archived&&language.id!==id)?.id||null;state=saveState(state);renderSelectedLanguages();renderCatalog();renderAnalytics();toast(t("languages.archived"));});}
function restoreLanguage(id){const item=state.languages.find(language=>language.id===id);if(!item)return;item.archived=false;if(!state.profile.defaultLanguageId)state.profile.defaultLanguageId=id;state=saveState(state);renderSelectedLanguages();renderCatalog();renderAnalytics();}

function activeLanguages(){return state.languages.filter(item=>!item.archived);}
function populateLanguageSelect(select,value=""){const items=activeLanguages();select.replaceChildren(new Option(t("languages.choose"),""),...items.map(item=>new Option(getLanguageDisplay(item,state.settings.uiLanguage),item.id)));select.value=value||state.profile.defaultLanguageId||"";renderSelectFlag(select);}
function renderSelectFlag(select){if(!select)return;let preview=select.parentElement.querySelector(":scope > .select-language-flags");if(!preview){preview=document.createElement("span");preview.className="select-language-flags";select.before(preview);}const item=state.languages.find(language=>language.id===select.value),key=item?.id||"";if(preview.dataset.languageId!==key){preview.dataset.languageId=key;preview.replaceChildren(createLanguageFlags(getLanguageCountryCodes(item)));}preview.hidden=!item;select.classList.toggle("has-language-flag",Boolean(item));}
function decorateRenderedLanguageNames(root=document){root.querySelectorAll(".today-session-row span:first-child,.session-main h2,.calendar-session span:first-child,.goal-card-head small,.language-bar-label>span:first-child,.language-table td:first-child").forEach(element=>{if(element.querySelector(":scope > .language-flags"))return;const language=state.languages.find(item=>element.textContent.trim().startsWith(getLanguageDisplay(item,state.settings.uiLanguage)));if(language)element.prepend(createLanguageFlags(getLanguageCountryCodes(language)));});}
function setupCustomCountryPicker(){const container=$("#custom-language"),save=$("#save-custom-language");if(!container||!save||$("#custom-language-country"))return;const field=document.createElement("label");field.className="field";field.innerHTML=`<span data-i18n="languages.customFlag"></span><select id="custom-language-country"></select>`;container.insertBefore(field,save);const select=field.querySelector("select"),locale=state.settings.uiLanguage==="ru"?"ru-RU":"en-US",names=new Intl.DisplayNames([locale],{type:"region"});select.append(new Option(t("languages.neutralFlag"),""),...availableCountryCodes.map(code=>new Option(names.of(code.toUpperCase())||code,code)).sort((a,b)=>a.text.localeCompare(b.text,locale)));select.addEventListener("change",()=>{let preview=field.querySelector(".select-language-flags");if(!preview){preview=document.createElement("span");preview.className="select-language-flags";select.before(preview);}preview.replaceChildren(createLanguageFlags(select.value?[select.value]:[]));select.classList.toggle("has-language-flag",Boolean(select.value));});}
function refreshCustomCountryPicker(){setupCustomCountryPicker();const select=$("#custom-language-country");if(!select)return;const current=select.value,locale=state.settings.uiLanguage==="ru"?"ru-RU":"en-US",names=new Intl.DisplayNames([locale],{type:"region"});select.replaceChildren(new Option(t("languages.neutralFlag"),""),...availableCountryCodes.map(code=>new Option(names.of(code.toUpperCase())||code,code)).sort((a,b)=>a.text.localeCompare(b.text,locale)));select.value=availableCountryCodes.includes(current)?current:"";select.dispatchEvent(new Event("change"));}
function activityOptions(selected=""){return`<option value="">${t("session.selectActivity")}</option>${activityCatalog.map(item=>`<option value="${item.id}" ${item.id===selected?"selected":""}>${t(`activity.${item.id}`)}</option>`).join("")}`;}
function durationParts(minutes=0){return{hours:Math.floor(minutes/60),minutes:minutes%60};}
function renderActivityRow(data={}){const category=activityCatalog.find(item=>item.id===data.categoryId)||activityCatalog[0];const parts=durationParts(Number(data.durationMinutes)||0);const row=document.createElement("section");row.className="activity-row";row.dataset.activityId=data.id||newId("activity");row.innerHTML=`<div class="activity-row-head"><label class="field"><span>${t("session.activity")}</span><select class="activity-category">${activityOptions(category.id)}</select></label><div class="duration-fields"><label class="field"><span>${t("session.hours")}</span><input class="activity-hours" type="number" min="0" max="24" value="${parts.hours}"></label><label class="field"><span>${t("session.minutes")}</span><input class="activity-minutes" type="number" min="0" max="59" value="${parts.minutes}"></label></div><button class="text-button archive remove-activity" type="button">${t("session.removeActivity")}</button></div><div class="activity-details"></div><label class="field"><span>${t("session.activityNotes")}</span><textarea class="activity-note" rows="2" placeholder="${t("session.notesPlaceholder")}">${escapeHtml(data.note||"")}</textarea></label>`;renderActivityDetails(row,category,data);return row;}
function renderActivityDetails(row,category,data={}){const container=row.querySelector(".activity-details");const selectedSub=data.subcategoryId||category.sub[0]||null;const fields=[];if(category.sub.length)fields.push(`<label class="field"><span>${t("detail.subcategory")}</span><select class="activity-subcategory">${category.sub.map(id=>`<option value="${id}" ${id===selectedSub?"selected":""}>${t(`sub.${id}`)}</option>`).join("")}</select></label>`);const detailFields=category.subFields?.[selectedSub]||category.fields;detailFields.forEach(field=>{const value=data.details?.[field.id]??(field.type==="multi"?[]:"");if(field.type==="multi"){fields.push(`<fieldset class="field multi-detail"><legend>${t(`detail.${field.id}`)}</legend><div class="skill-options">${field.options.map(option=>`<label><input type="checkbox" data-multi-detail="${field.id}" value="${option}" ${value.includes(option)?"checked":""}><span>${t(`skill.${option}`)}</span></label>`).join("")}</div></fieldset>`);}else fields.push(`<label class="field"><span>${t(`detail.${field.id}`)}</span><input data-detail="${field.id}" type="${field.type}" min="0" value="${escapeHtml(String(value))}"></label>`);});container.innerHTML=fields.join("");}
function collectActivities(){return $$('#activity-editor .activity-row').map(row=>{const hours=Number(row.querySelector('.activity-hours').value)||0;const minutes=Number(row.querySelector('.activity-minutes').value)||0;const categoryId=row.querySelector('.activity-category').value;const subcategoryId=row.querySelector('.activity-subcategory')?.value||null;const details={};row.querySelectorAll('[data-detail]').forEach(input=>{if(input.value!=="")details[input.dataset.detail]=input.type==="number"?Number(input.value):input.value.trim();});row.querySelectorAll('[data-multi-detail]').forEach(input=>{details[input.dataset.multiDetail]??=[];if(input.checked)details[input.dataset.multiDetail].push(input.value);});if(categoryId==="integrated-learning"&&subcategoryId==="tutor"){details.tutorName??="";details.lessonTopic??="";details.practisedSkills??=[];}return{id:row.dataset.activityId,categoryId,subcategoryId,durationMinutes:hours*60+minutes,details,note:row.querySelector('.activity-note').value.trim()};});}
function calculateEndTime(start,total){if(!start||!total)return"—";const[hours,minutes]=start.split(':').map(Number);const end=(hours*60+minutes+total)%(24*60);return`${String(Math.floor(end/60)).padStart(2,"0")}:${String(end%60).padStart(2,"0")}`;}
function updateSessionTotals(){const total=collectActivities().reduce((sum,item)=>sum+item.durationMinutes,0);$("#session-total").textContent=String(total);$("#session-end").textContent=calculateEndTime($("#session-start").value,total);return total;}
function openSessionForm(session=null){$("#session-edit-id").value=session?.id||"";$("#session-dialog-title").textContent=t(session?"journal.edit":"journal.add");populateLanguageSelect($("#session-language"),session?.languageId);$("#session-date").value=session?.date||todayKey();$("#session-start").value=session?.startTime||new Date().toTimeString().slice(0,5);$("#session-notes").value=session?.note||"";const editor=$("#activity-editor");editor.replaceChildren(...(session?.activities?.length?session.activities:[{categoryId:"reading",durationMinutes:30}]).map(renderActivityRow));updateSessionTotals();$("#session-dialog").showModal();}
function buildManualSession(){const activities=collectActivities();const total=activities.reduce((sum,item)=>sum+item.durationMinutes,0);if(!$("#session-language").value||!activities.length||activities.some(item=>!item.categoryId||item.durationMinutes<=0)){toast(t("session.invalid"));return null;}const now=new Date().toISOString();const existing=state.sessions.find(item=>item.id===$("#session-edit-id").value);return{id:existing?.id||newId("session"),date:$("#session-date").value,startTime:$("#session-start").value,endTime:calculateEndTime($("#session-start").value,total),startedAt:`${$("#session-date").value}T${$("#session-start").value}:00`,durationMinutes:total,languageId:$("#session-language").value,categoryId:activities[0].categoryId,subcategoryId:activities[0].subcategoryId,activities,source:"manual",note:$("#session-notes").value.trim(),createdAt:existing?.createdAt||now,updatedAt:now};}
function saveManualSession(session){const index=state.sessions.findIndex(item=>item.id===session.id);if(index>=0)state.sessions[index]=session;else state.sessions.push(session);state=saveState(state);$("#session-dialog").close();renderJournal();renderCalendar();renderGoals();renderAnalytics();toast(t(index>=0?"journal.updated":"journal.saved"));}
function sessionLanguage(session){return getLanguageDisplay(state.languages.find(item=>item.id===session.languageId),state.settings.uiLanguage)||t("languages.choose");}
function activityLabel(item){const category=t(`activity.${item.categoryId}`);return item.subcategoryId?`${category} · ${t(`sub.${item.subcategoryId}`)}`:category;}
function renderJournal(){const sessions=[...state.sessions].sort((a,b)=>(`${b.date} ${b.startTime||""}`).localeCompare(`${a.date} ${a.startTime||""}`));$("#journal-total").textContent=String(sessions.reduce((sum,item)=>sum+item.durationMinutes,0));$("#journal-count").textContent=String(sessions.length);const todaySessions=sessions.filter(item=>item.date===todayKey());$("#today-minutes").textContent=String(todaySessions.reduce((sum,item)=>sum+item.durationMinutes,0));$("#today-session-empty").hidden=todaySessions.length>0;$("#today-session-list").replaceChildren(...todaySessions.slice(0,3).map(session=>{const row=document.createElement("div");row.className="today-session-row";row.innerHTML=`<span><strong>${escapeHtml(sessionLanguage(session))}</strong><small>${escapeHtml(activityLabel(session.activities?.[0]||session))}</small></span><span>${session.startTime||""}</span><strong>${formatMinutes(session.durationMinutes)}</strong>`;return row;}));$("#journal-empty").hidden=sessions.length>0;const locale=state.settings.uiLanguage==="ru"?"ru-RU":"en-US";$("#session-list").replaceChildren(...sessions.map(session=>{const date=new Date(`${session.date}T12:00:00`);const card=document.createElement("article");card.className="card session-card";const activityNames=(session.activities?.length?session.activities:[{categoryId:session.categoryId,subcategoryId:session.subcategoryId}]).map(activityLabel).join(" · ");card.innerHTML=`<div class="session-date-badge"><strong>${date.getDate()}</strong><small>${new Intl.DateTimeFormat(locale,{month:"short"}).format(date)}</small></div><div class="session-main"><h2>${escapeHtml(sessionLanguage(session))} · ${session.durationMinutes} ${t("session.minutesShort")}</h2><div class="session-meta"><span class="source-chip">${t(`journal.source.${session.source}`)}</span><span>${session.startTime||""}${session.endTime?`–${session.endTime}`:""}</span></div><div class="session-activities">${escapeHtml(activityNames)}</div></div>${session.source==="manual"?`<div class="session-card-actions"><button class="text-button" type="button" data-edit-session="${session.id}">${t("journal.edit")}</button><button class="text-button archive" type="button" data-delete-session="${session.id}">${t("journal.delete")}</button></div>`:""}`;return card;}));}
function deleteSession(id){openConfirm(t("journal.deleteTitle"),t("journal.deleteText"),t("journal.delete"),()=>{state.sessions=state.sessions.filter(item=>item.id!==id);state=saveState(state);renderJournal();renderCalendar();renderGoals();renderAnalytics();toast(t("journal.deleted"));});}

function renderCalendar(){
  const locale=state.settings.uiLanguage==="ru"?"ru-RU":"en-US";const totals=dailyTotals(state.sessions);const year=calendarCursor.getFullYear();const month=calendarCursor.getMonth();const today=dateKey(new Date());
  const monthName=new Intl.DateTimeFormat(locale,{month:"long"}).format(calendarCursor);const monthTitle=`${monthName} ${calendarCursor.getFullYear()}`;$("#calendar-month").innerHTML=`<span>${monthTitle}</span><small id="calendar-current-time"></small>`;updateCalendarClock();
  const monday=new Date(2026,0,5,12);$("#calendar-weekdays").replaceChildren(...Array.from({length:7},(_,index)=>{const item=document.createElement("span");const date=new Date(monday);date.setDate(date.getDate()+index);item.textContent=new Intl.DateTimeFormat(locale,{weekday:"short"}).format(date);return item;}));
  const first=new Date(year,month,1,12);const offset=(first.getDay()+6)%7;const days=new Date(year,month+1,0,12).getDate();const cells=Array.from({length:offset},()=>{const spacer=document.createElement("span");spacer.className="calendar-spacer";return spacer;});
  for(let day=1;day<=days;day+=1){const date=new Date(year,month,day,12);const key=dateKey(date);const minutes=totals[key]||0;const button=document.createElement("button");button.type="button";button.className=`calendar-day${minutes>=15?" complete":minutes>0?" partial":""}${key===today?" today":""}${key===calendarSelectedDate?" selected":""}`;button.dataset.calendarDate=key;button.setAttribute("aria-pressed",String(key===calendarSelectedDate));button.setAttribute("aria-label",`${new Intl.DateTimeFormat(locale,{day:"numeric",month:"long",year:"numeric"}).format(date)}. ${minutes} ${t("session.minutesShort")}. ${t(minutes>=15?"calendar.completeStatus":minutes>0?"calendar.partialStatus":"calendar.emptyStatus")}`);button.innerHTML=`<span>${day}</span>${minutes?`<small>${minutes}</small>`:""}<i aria-hidden="true"></i>`;cells.push(button);}
  $("#calendar-grid").replaceChildren(...cells);const series=streaks(state.sessions);$("#calendar-current-streak").textContent=String(series.current);$("#calendar-best-streak").textContent=String(series.best);$("#today-streak").textContent=String(series.current);$("#calendar-month-achievement").hidden=!isFullMonth(state.sessions,year,month);renderCalendarDay();
}
function renderCalendarDay(){const locale=state.settings.uiLanguage==="ru"?"ru-RU":"en-US";const sessions=state.sessions.filter(item=>item.date===calendarSelectedDate).sort((a,b)=>(a.startTime||"").localeCompare(b.startTime||""));const minutes=sessions.reduce((sum,item)=>sum+item.durationMinutes,0);const dateParts=calendarSelectedDate.split("-").map(Number);const date=new Date(dateParts[0],dateParts[1]-1,dateParts[2],12);const selectedDate=new Intl.DateTimeFormat(locale,{weekday:"long",day:"numeric",month:"long",year:"numeric"}).format(date).replace(/\s*г\.$/u,"");$("#calendar-selected-date").textContent=selectedDate;$("#calendar-day-minutes").textContent=String(minutes);$("#calendar-day-message").textContent=t(minutes>=15?"calendar.completeMessage":minutes>0?"calendar.partialMessage":"calendar.emptyMessage");$("#calendar-day-message").className=minutes>=15?"complete-message":minutes>0?"partial-message":"";$("#calendar-day-sessions").replaceChildren(...sessions.map(session=>{const item=document.createElement("div");item.className="calendar-session";const category=activityCatalog.some(entry=>entry.id===session.categoryId)?session.categoryId:"other";item.innerHTML=`<span><strong>${escapeHtml(sessionLanguage(session))}</strong><small>${t(`activity.${category}`)}</small></span><strong>${session.durationMinutes} ${t("session.minutesShort")}</strong>`;return item;}));}
function moveCalendarMonth(delta){calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+delta,1,12);calendarSelectedDate=dateKey(calendarCursor);renderCalendar();}
