function nextMotivationIndex(){const last=state.notifications.at(-1)?.messageIndex;let index=Math.floor(Math.random()*motivation.ru.length);if(index===last)index=(index+1)%motivation.ru.length;return index;}
function celebrate(type,id){if(state.achievements.includes(id))return;const messageIndex=nextMotivationIndex();state.achievements.push(id);state.notifications.push({id:newId("notice"),type,messageIndex,createdAt:new Date().toISOString()});state=saveState(state);toast(motivation[state.settings.uiLanguage][messageIndex]);}
