function ensureLanguageOverview(){let overview=$("#language-overview");if(!overview){overview=document.createElement("article");overview.className="card language-overview";overview.id="language-overview";overview.innerHTML=`<div class="insight-breadcrumb" id="insight-breadcrumb"></div><div class="section-heading"><div><p class="eyebrow" data-i18n="insights.languagesEyebrow"></p><h2 data-i18n="insights.byLanguage"></h2></div></div><div class="language-bars" id="language-bars"></div><div class="sr-only" id="language-table-label" data-i18n="insights.languageTable"></div><table class="language-table" aria-labelledby="language-table-label"><thead><tr><th data-i18n="session.language"></th><th data-i18n="insights.totalTime"></th><th data-i18n="insights.share"></th></tr></thead><tbody id="language-table-body"></tbody></table><p class="empty" id="language-overview-empty" hidden data-i18n="insights.empty"></p>`;$(".insight-layout").before(overview);}overview.querySelectorAll("[data-i18n]").forEach(element=>element.textContent=t(element.dataset.i18n));return overview;}
