function startOrResumeFocus(){if(!state.focusTimer){const languageId=$("#focus-language").value;if(!languageId){toast(t("focus.needLanguage"));return;}state.focusTimer={id:newId("focus"),status:"running",languageId,categoryId:$("#focus-activity").value,subcategoryId:$("#focus-subcategory").value||null,targetMinutes:focusPresetMinutes,startedAt:Date.now(),elapsedSeconds:0,createdAt:new Date().toISOString()};}else if(state.focusTimer.status==="paused"){state.focusTimer.status="running";state.focusTimer.startedAt=Date.now();}state=saveState(state);startFocusTicker();updateFocusDisplay();}
